{
  "charges": [
    {
      "claim": "Empty keepQueryParameters array removes all query parameters instead of preserving them",
      "file": "index.js",
      "line": 229,
      "severity": "major",
      "witnessCode": "import { strict as assert } from 'node:assert';\nimport { test } from 'node:test';\nimport { normalizeUrl } from '../index.js';\n\ntest('keepQueryParameters: [] should preserve all query parameters', () => {\n  const url = 'http://example.com?foo=bar&baz=qux';\n  const options = { keepQueryParameters: [] };\n  const result = normalizeUrl(url, options);\n  const expected = 'http://example.com?foo=bar&baz=qux';\n  assert.strictEqual(result, expected);\n});"
    }
  ]
}
